module parallel2serial (
    input wire clk,
    input wire rst_n,
    input wire [3:0]d,
    output reg valid_out,
    output reg dout
);

reg [1:0] cnt;
always @(posedge clk or negedge rst_n) begin
    if(!rst_n) cnt <= 2'b0; else cnt <= cnt + 1;
end

reg [3:0] data;
always @(posedge clk or negedge rst_n) begin
    if(!rst_n)
        data <= 4'b0;
    else if(cnt == 2'b11) begin
        data <= d;
        valid_out <= 1'b1;
    end
    else begin
        data <= {data[2:0], 1'b0};
        valid_out <= 1'b0;
    end
end

assign dout = data[3];
endmodule
